#include <Servo.h>

Servo myServo;

int startAngle = 90;  // Исходное положение
int targetAngle = 0;  // Поворот влево на 90 градусов

void setup() {
  myServo.attach(9);       // Сигнал сервомотора подключён к пину 9
  myServo.write(startAngle);
  delay(1000);
}

void loop() {
  // Медленно поворачиваем влево с 90° до 0°
  for (int angle = startAngle; angle >= targetAngle; angle--) {
    myServo.write(angle);
    delay(20);  // Чем больше значение, тем медленнее движение
  }

  // Ждём 2 секунды
  delay(2000);

  // Медленно возвращаемся в исходное положение
  for (int angle = targetAngle; angle <= startAngle; angle++) {
    myServo.write(angle);
    delay(20);
  }

  // Ждём перед повторением
  delay(1000);
}
